def migrate_legacy_tax_and_numbers(apps, schema_editor):
    Invoice = apps.get_model('tenantdata', 'Invoice')
    Quote = apps.get_model('tenantdata', 'Quote')
    TaxRule = apps.get_model('tenantdata', 'TaxRule')

    for document_model, number_field, prefix in (
        (Invoice, 'invoice_number', 'FAC'),
        (Quote, 'quote_number', 'QUO'),
    ):
        for document in document_model.objects.select_related('business').all():
            current_number = getattr(document, number_field)
            if not current_number:
                setattr(document, number_field, f'{prefix}-LEGACY-{document.pk:06d}')
                document.save(update_fields=[number_field])

            percentage = document.tax_percentage
            if percentage and percentage > 0:
                rule, _ = TaxRule.objects.get_or_create(
                    business=document.business,
                    name=f'IVA {percentage}%',
                    rule_type='IVA',
                    defaults={'percentage': percentage, 'is_active': True},
                )
                document.tax_rules.add(rule)


